  --surface: rgba(255, 252, 244, 0.9);
  --surface-solid: #fffaf0;
  --surface-soft: rgba(23, 51, 107, 0.06);
  --text: #16233b;
  --muted: #596174;
  --line: rgba(23, 51, 107, 0.16);
  --accent: #17336b;
  --accent-2: #aa4520;
  --accent-text: #ffffff;
  --glow: rgba(220, 107, 63, 0.13);
  --nav: rgba(244, 240, 231, 0.86);
  --shadow: 0 28px 70px rgba(52, 45, 35, 0.13);
}

:root[data-theme="console"] {
  --bg: #101614;
  --surface: rgba(22, 32, 29, 0.9);
  --surface-solid: #16201d;
  --surface-soft: rgba(98, 245, 195, 0.055);
  --text: #e8fff7;
  --muted: #a5beb6;
  --line: rgba(98, 245, 195, 0.14);
  --accent: #62f5c3;
  --accent-2: #a5ff6b;
  --accent-text: #08130f;
  --glow: rgba(98, 245, 195, 0.17);
  --nav: rgba(16, 22, 20, 0.88);
}

:root[data-theme="synthwave"] {
  --bg: #07071b;
  --surface: rgba(15, 12, 42, 0.84);
  --surface-solid: #100d2d;
  --surface-soft: rgba(255, 255, 255, 0.06);
  --text: #fbf7ff;
  --muted: #c1bddc;
  --line: rgba(91, 222, 255, 0.2);
  --accent: #ff3dbb;
  --accent-2: #18d8ff;
  --accent-text: #12051a;
  --glow: rgba(255, 61, 187, 0.26);
  --nav: rgba(7, 7, 27, 0.78);
  --shadow: 0 30px 90px rgba(2, 2, 18, 0.52);
}

:root[data-theme="system"] {
  --bg: #f7f9ff;
  --surface: rgba(255, 255, 255, 0.86);
  --surface-solid: #ffffff;
  --surface-soft: rgba(28, 52, 96, 0.055);
  --text: #182033;
  --muted: #596174;
  --line: rgba(24, 32, 51, 0.12);
  --accent: #5a3fe0;
  --accent-2: #0d6fa9;
  --accent-text: #ffffff;
  --glow: rgba(115, 87, 255, 0.16);
  --nav: rgba(247, 249, 255, 0.82);
}

:root[data-theme="aurora"] {
  --bg: #07091a;
  --surface: rgba(18, 20, 49, 0.74);
  --surface-solid: #121431;
  --surface-soft: rgba(255, 255, 255, 0.055);
  --text: #f7f7ff;
  --muted: #b8bbd3;
  --line: rgba(255, 255, 255, 0.12);
  --accent: #8b5cf6;
  --accent-2: #22d3ee;
  --accent-text: #020605;
  --glow: rgba(116, 78, 255, 0.3);
  --nav: rgba(7, 9, 26, 0.72);
}

:root[data-custom="true"][data-theme] {
  color-scheme: var(--custom-color-scheme, light);
  --bg: var(--custom-background);
  --surface: color-mix(in srgb, var(--custom-background) 90%, var(--custom-text));
  --surface-solid: color-mix(in srgb, var(--custom-background) 92%, var(--custom-text));
  --surface-soft: color-mix(in srgb, var(--custom-background) 94%, var(--custom-text));
  --text: var(--custom-text);
  --muted: color-mix(in srgb, var(--custom-text) 78%, var(--custom-background));
  --line: color-mix(in srgb, var(--custom-text) 20%, transparent);
  --accent: var(--custom-accent);
  --accent-2: var(--custom-secondary);
  --accent-text: var(--custom-accent-text);
  --nav: color-mix(in srgb, var(--custom-background) 84%, transparent);
}

@media (prefers-color-scheme: dark) {
  :root[data-theme="system"] {
    color-scheme: dark;
    --bg: #090d18;
    --surface: rgba(20, 26, 42, 0.82);
    --surface-solid: #141a2a;
    --surface-soft: rgba(255, 255, 255, 0.05);
    --text: #eaf0ff;
    --muted: #98a5bd;
    --line: rgba(255, 255, 255, 0.1);
    --accent: #a99aff;
    --accent-2: #7dd3fc;
    --accent-text: #080b14;
    --glow: rgba(169, 154, 255, 0.16);
    --nav: rgba(9, 13, 24, 0.84);
  }
}

:root {
  color-scheme: light;
  background-color: var(--bg);
}

:root[data-theme="dark"],
:root[data-theme="aurora"],
:root[data-theme="console"],
:root[data-theme="synthwave"] {
  color-scheme: dark;
  --positive: #64e1b4;
  --positive-soft: rgba(100, 225, 180, 0.1);
  --warning: #ffd27c;
  --warning-soft: rgba(255, 210, 124, 0.1);
  --danger: #ffb4bc;
  --danger-soft: rgba(255, 180, 188, 0.1);
}

@media (prefers-color-scheme: dark) {
  :root[data-theme="system"] {
    --positive: #64e1b4;
    --positive-soft: rgba(100, 225, 180, 0.1);
    --warning: #ffd27c;
    --warning-soft: rgba(255, 210, 124, 0.1);
    --danger: #ffb4bc;
    --danger-soft: rgba(255, 180, 188, 0.1);
  }
}

:root[data-theme="light"],
:root[data-theme="editorial"] {
  color-scheme: light;
}

:root[data-custom="true"] {
  color-scheme: var(--custom-color-scheme, light);
}

* { box-sizing: border-box; }
html {
  min-height: 100%;
  scroll-behavior: smooth;
  background-color: var(--bg);
  transition: background-color .3s ease;
}
section[id], main[id] { scroll-margin-top: 110px; }
body {
  min-height: 100%;
  margin: 0;
  background-color: var(--bg);
  color: var(--text);
  transition: background-color .3s ease, color .3s ease;
  font-family: var(--font-geist-sans), "Pretendard", "Noto Sans KR",
    "Noto Sans JP", "Noto Sans SC", "Apple SD Gothic Neo", "Yu Gothic",
    "Microsoft YaHei", Arial, sans-serif;
}
button, input, select, textarea { font: inherit; }
a { color: inherit; text-decoration: none; }

.site-shell {
  min-height: 100vh;
  overflow: hidden;
  position: relative;
  background:
    radial-gradient(circle at 50% -10%, var(--glow), transparent 35%),
    linear-gradient(180deg, color-mix(in srgb, var(--bg) 90%, var(--accent) 10%), var(--bg) 36%);
  transition: background .35s ease, color .35s ease;
}

.privacy-shell {
  min-height: 100vh;
  overflow: hidden;
  position: relative;
  background:
    radial-gradient(circle at 15% 0%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 28%),
    radial-gradient(circle at 85% 15%, color-mix(in srgb, var(--accent-2) 15%, transparent), transparent 27%),
    linear-gradient(180deg, color-mix(in srgb, var(--bg) 92%, var(--accent) 8%), var(--bg) 35%, color-mix(in srgb, var(--bg) 96%, var(--accent-2) 4%));
}
.privacy-topbar {
  width: min(1120px, calc(100% - 40px));
  min-height: 72px;
  margin: 18px auto 0;
  padding: 13px 18px 13px 22px;
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--nav);
  backdrop-filter: blur(20px);
  box-shadow: 0 12px 38px rgba(0, 0, 0, .14);
}
.privacy-home-link {
  min-height: 40px;
  padding: 0 15px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-soft);
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
}
.privacy-home-link span { color: var(--accent-2); }
.privacy-document {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
  position: relative;
  z-index: 1;
}
.privacy-hero {
  padding: 112px 0 74px;
  border-bottom: 1px solid var(--line);
}
.privacy-hero h1 {
  max-width: 900px;
  margin: 18px 0;
  font-size: clamp(46px, 7vw, 78px);
  line-height: 1.04;
  letter-spacing: -.06em;
}
.privacy-hero > p {
  max-width: 780px;
  margin: 0;
  color: var(--muted);
  font-size: 17px;
  line-height: 1.85;
}
.policy-meta {
  margin-top: 32px;
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}
.privacy-language-note {
  margin-top: 22px !important;
  color: var(--accent-2) !important;
  font-size: 11px !important;
  font-weight: 800;
  letter-spacing: .04em;
}
.policy-meta span {
  padding: 8px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-soft);
  color: var(--muted);
  font-size: 10px;
}
.policy-meta b, .policy-meta time { color: var(--text); }
.privacy-toc {
  padding: 24px 0;
  position: sticky;
  top: 0;
  z-index: 4;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  background: color-mix(in srgb, var(--bg) 86%, transparent);
  backdrop-filter: blur(18px);
}
.privacy-toc a {
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
}
.privacy-toc a:hover { color: var(--text); border-color: var(--accent-2); }
.privacy-section {
  padding: 68px 0;
  scroll-margin-top: 84px;
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: minmax(220px, .6fr) minmax(0, 1.4fr);
  gap: 74px;
}
.privacy-section > div:first-child { align-self: start; }
.privacy-number {
  color: var(--accent-2);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .18em;
}
.privacy-section h2 {
  margin: 13px 0 0;
  font-size: clamp(27px, 3.5vw, 40px);
  line-height: 1.15;
  letter-spacing: -.045em;
}
.privacy-copy {
  min-width: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.85;
}
.privacy-copy > :first-child { margin-top: 0; }
.privacy-copy > :last-child { margin-bottom: 0; }
.privacy-copy a, .english-summary a { color: var(--accent-2); text-decoration: underline; text-underline-offset: 3px; }
.privacy-copy code, .english-summary code {
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-soft);
  color: var(--text);
  font-family: var(--font-geist-mono), monospace;
  font-size: .88em;
}
.privacy-copy ul, .privacy-copy ol, .english-summary ul {
  margin: 18px 0 0;
  padding-inline-start: 22px;
  display: grid;
  gap: 10px;
}
.privacy-copy li::marker, .english-summary li::marker { color: var(--accent-2); }
.privacy-copy strong { color: var(--text); }
.privacy-columns {
  margin-top: 26px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.privacy-columns > div {
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: var(--surface-soft);
}
.privacy-columns h3 {
  margin: 0;
  color: var(--text);
  font-size: 14px;
}
.privacy-columns ul { font-size: 12px; }
.privacy-note {
  margin-top: 22px;
  padding: 15px 17px;
  border-inline-start: 2px solid var(--accent-2);
  background: var(--surface-soft);
  font-size: 12px;
}
.privacy-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 17px;
}
.privacy-table-wrap table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
  background: var(--surface-soft);
  text-align: left;
}
.privacy-table-wrap caption {
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
  color: var(--text);
  text-align: left;
  font-size: 13px;
  font-weight: 800;
}
.privacy-table-wrap th, .privacy-table-wrap td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
  font-size: 11px;
  line-height: 1.65;
}
.privacy-table-wrap thead th {
  color: var(--accent-2);
  font-size: 9px;
  letter-spacing: .08em;
}
.privacy-table-wrap tbody th { color: var(--text); }
.privacy-table-wrap tr:last-child > * { border-bottom: 0; }
.limited-use {
  margin-top: 24px;
  padding: 22px;
  border: 1px solid color-mix(in srgb, var(--accent-2) 42%, var(--line));
  border-radius: 17px;
  background: color-mix(in srgb, var(--accent-2) 5%, var(--surface-soft));
}
.limited-use > strong { color: var(--accent-2); font-size: 12px; letter-spacing: .06em; }
.limited-use p:last-child { margin-bottom: 0; font-size: 12px; }
.english-summary {
  margin: 78px 0 28px;
  padding: 38px;
  scroll-margin-top: 84px;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--line));
  border-radius: 23px;
  background: linear-gradient(145deg, rgba(255, 61, 187, .08), rgba(24, 216, 255, .06));
  color: var(--muted);
  font-size: 13px;
  line-height: 1.8;
}
.english-summary h2 {
  margin: 10px 0 16px;
  color: var(--text);
  font-size: 32px;
  letter-spacing: -.04em;
}
.privacy-footer { width: 100%; }

.ambient { position: absolute; border-radius: 50%; filter: blur(100px); opacity: .36; pointer-events: none; }
.ambient-one { width: 480px; height: 480px; background: var(--accent); top: 180px; right: -270px; }
.ambient-two { width: 340px; height: 340px; background: var(--accent-2); top: 760px; left: -250px; opacity: .16; }

.topbar {
  width: min(1180px, calc(100% - 40px));
  height: 74px;
  margin: 18px auto 0;
  padding: 0 18px 0 22px;
  position: sticky;
  top: 14px;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--nav);
  backdrop-filter: blur(20px);
  box-shadow: 0 12px 38px rgba(0, 0, 0, .14);
}

.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; letter-spacing: -.03em; }
.brand-avatar {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--accent-2) 60%, var(--line));
  border-radius: 50%;
  object-fit: cover;
  box-shadow: 0 0 24px var(--glow);
}
.brand small { margin-left: 2px; color: var(--muted); font-size: 10px; font-weight: 500; letter-spacing: .05em; }
.main-nav { display: flex; gap: 25px; font-size: 13px; color: var(--muted); }
.main-nav a:hover { color: var(--text); }
.header-actions,
.preference-actions { display: flex; align-items: center; gap: 10px; }
.theme-anchor, .language-anchor { position: relative; }
.theme-trigger, .language-trigger, .install-small {
  height: 40px; padding: 0 15px; border: 1px solid var(--line); border-radius: 11px; background: var(--surface-soft); color: var(--text);
  display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13px; font-weight: 700;
}
.language-trigger { min-width: 62px; justify-content: center; padding-inline: 11px; }
.language-trigger > span:first-child { color: var(--accent-2); font-size: 16px; }
.language-trigger b { font-size: 11px; letter-spacing: .05em; }
.theme-trigger:hover, .language-trigger:hover { border-color: color-mix(in srgb, var(--accent) 58%, var(--line)); }
.palette-icon { color: var(--accent-2); font-size: 17px; }
.theme-trigger-character {
  width: 23px;
  height: 23px;
  position: relative;
  flex: 0 0 auto;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--line));
  border-radius: 50%;
  background: var(--surface-solid);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--accent) 16%, transparent);
}
.theme-trigger-character img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: 50% 44%;
  transform: scale(1.08);
}
.theme-trigger-character-layer {
  display: none !important;
}
:root:not([data-character]) .theme-trigger-character-layer[data-character-layer="aiwork"],
:root[data-character="aiwork"] .theme-trigger-character-layer[data-character-layer="aiwork"],
:root[data-character="planner"] .theme-trigger-character-layer[data-character-layer="planner"] {
  display: block !important;
}
.chevron { color: var(--muted); font-size: 8px; margin-left: 2px; }
.install-small { border-color: transparent; background: var(--accent); color: var(--accent-text); padding-inline: 18px; }

.theme-menu, .language-menu {
  position: absolute; width: 390px; right: 0; top: 52px; padding: 18px; border: 1px solid var(--line); border-radius: 20px;
  background: color-mix(in srgb, var(--surface-solid) 94%, transparent); backdrop-filter: blur(24px); box-shadow: var(--shadow);
}
.theme-menu { max-height: min(680px, calc(100vh - 100px)); overflow-y: auto; }
.language-menu {
  width: 258px;
  max-height: min(680px, calc(100vh - 100px));
  overflow-y: auto;
}
.theme-menu-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14px; }
.theme-menu-head div { display: grid; gap: 4px; }
.theme-menu-head strong { font-size: 15px; }
.theme-menu-head span, .custom-link small { color: var(--muted); font-size: 11px; }
.theme-menu-head button, .custom-head > button { border: 0; background: transparent; color: var(--muted); font-size: 24px; cursor: pointer; }
.theme-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.theme-option {
  min-height: 84px; padding: 12px; position: relative; text-align: left; border: 1px solid var(--line); border-radius: 13px;
  background: var(--surface-soft); color: var(--text); display: grid; gap: 5px; cursor: pointer;
}
.theme-option:hover, .theme-option.active { border-color: color-mix(in srgb, var(--accent) 70%, var(--line)); background: color-mix(in srgb, var(--accent) 10%, var(--surface-soft)); }
.theme-option strong { font-size: 12px; }
.theme-option small { color: var(--muted); font-size: 9px; }
.theme-option b { position: absolute; top: 10px; right: 10px; width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%; background: var(--accent); color: var(--accent-text); font-size: 11px; }
.swatches { display: flex; height: 18px; width: 64px; overflow: hidden; border-radius: 5px; border: 1px solid var(--line); }
.swatches i { flex: 1; }
.custom-link {
  width: 100%; margin-top: 10px; padding: 12px 13px; border: 1px solid var(--line); border-radius: 13px; background: var(--surface-soft); color: var(--text);
  display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; text-align: left; cursor: pointer;
}
.custom-link.active {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-soft));
}
.custom-link > span:first-child { color: var(--accent-2); font-size: 18px; }
.custom-link > span:nth-child(2) { display: grid; gap: 3px; }
.custom-link b { color: var(--accent-2); }

.character-picker {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.character-picker-head {
  margin-bottom: 10px;
  display: grid;
  gap: 3px;
}
.character-picker-head strong {
  color: var(--text);
  font-size: 13px;
}
.character-picker-head span {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}
.character-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.character-option {
  min-height: 82px;
  padding: 11px;
  position: relative;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface-soft);
  color: var(--text);
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  text-align: start;
  cursor: pointer;
}
.character-option:hover,
.character-option.active {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-soft));
}
.character-option:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 36%, transparent);
  outline-offset: 2px;
}
.character-option-image {
  width: 48px;
  height: 48px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: 50%;
  background: var(--surface-solid);
  box-shadow: 0 5px 15px color-mix(in srgb, var(--accent) 14%, transparent);
}
.character-option-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: 50% 44%;
  transform: scale(1.07);
}
.character-option > span:nth-child(2) {
  min-width: 0;
  display: grid;
  gap: 3px;
}
.character-option strong {
  padding-inline-end: 20px;
  font-size: 12px;
  line-height: 1.25;
}
.character-option small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}
.character-option > b {
  width: 20px;
  height: 20px;
  position: absolute;
  inset-block-start: 9px;
  inset-inline-end: 9px;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-text);
  display: grid;
  place-items: center;
  font-size: 11px;
}

.language-list { display: grid; gap: 7px; }
.language-option {
  min-height: 48px;
  padding: 8px 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-soft);
  color: var(--text);
  display: grid;
  grid-template-columns: 34px 1fr auto;
  gap: 10px;
  align-items: center;
