  .site-footer { grid-template-columns: 1fr; gap: 12px; }.footer-brand + p { margin-top: 4px; }
  .footer-links { justify-content: flex-start; }
  .custom-panel { padding: 21px; }.custom-actions { grid-template-columns: 1fr; }
  .privacy-topbar, .privacy-document { width: calc(100% - 24px); }
  .privacy-topbar { min-height: 66px; margin-top: 10px; padding-inline: 13px; }
  .privacy-home-link { padding-inline: 11px; font-size: 10px; }
  .privacy-hero { padding: 78px 0 56px; }
  .privacy-hero h1 { font-size: 44px; }
  .privacy-hero > p { font-size: 14px; }
  .privacy-toc { padding: 16px 0; }
  .privacy-section { padding: 52px 0; }
  .privacy-columns { grid-template-columns: 1fr; }
  .privacy-columns > div { padding: 18px; }
  .english-summary { margin-top: 58px; padding: 24px; }
  .english-summary h2 { font-size: 27px; }
}

/* Shared multi-page navigation and footer */

:focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: 4px;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 12px;
  left: 12px;
  padding: 11px 15px;
  border-radius: 10px;
  background: var(--surface-solid);
  color: var(--text);
  box-shadow: var(--shadow);
  transform: translateY(-180%);
  transition: transform .15s ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.section-topbar {
  width: min(1180px, calc(100% - 40px));
}

.section-nav a {
  padding: 8px 2px;
  position: relative;
}

.section-nav a::after {
  content: "";
  width: 0;
  height: 2px;
  position: absolute;
  left: 0;
  bottom: 2px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  transition: width .2s ease;
}

.section-nav a:hover::after,
.section-nav a.active::after {
  width: 100%;
}

.section-nav a.active {
  color: var(--text);
}

.section-mobile-nav {
  display: none;
}

.site-footer {
  margin-top: 80px;
  padding: 42px 0 56px;
  border-top: 1px solid var(--line);
  grid-template-columns: minmax(240px, 1fr) auto;
  gap: 28px 50px;
  align-items: start;
}

.footer-intro {
  display: grid;
  gap: 13px;
}

.footer-intro p {
  margin: 0;
}

.site-footer .footer-links {
  align-self: center;
}

.business-details {
  grid-column: 1 / -1;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--surface-soft);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 24px;
  color: var(--muted);
  font-style: normal;
  line-height: 1.65;
}

.business-details strong {
  color: var(--text);
}

.footer-legal {
  grid-column: 1 / -1;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  display: grid;
  gap: 15px;
}

.site-footer .footer-legal small {
  padding: 0;
  border: 0;
  color: var(--text);
}

.footer-legal p {
  max-width: 980px;
  margin: 0;
  font-size: 11px;
  line-height: 1.75;
}

/* Detail pages */

.detail-shell {
  min-height: 100vh;
}

.detail-page {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

.detail-hero {
  min-height: 0;
  padding: 64px 0 56px;
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(360px, .98fr);
  gap: clamp(38px, 5vw, 64px);
  align-items: center;
}

.detail-hero-copy {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.detail-hero-copy h1 {
  width: 100%;
  margin: 18px 0 20px;
  font-size: clamp(48px, 6.6vw, 76px);
  line-height: 1.04;
  letter-spacing: -.06em;
}

.detail-hero-copy > p {
  width: 100%;
  max-width: 64ch;
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.7;
}

.status-pill,
.mini-status {
  width: fit-content;
  border: 1px solid color-mix(in srgb, var(--accent-2) 45%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-2) 8%, var(--surface-soft));
  color: var(--accent-2);
  font-size: 9px;
  font-weight: 800;
}

.status-pill {
  padding: 7px 10px;
  letter-spacing: .04em;
}

.mini-status {
  padding: 6px 8px;
  white-space: nowrap;
}

.mini-status.positive {
  border-color: color-mix(in srgb, var(--positive) 38%, var(--line));
  background: var(--positive-soft);
  color: var(--positive);
}

.mini-status.caution {
  border-color: color-mix(in srgb, var(--warning) 38%, var(--line));
  background: var(--warning-soft);
  color: var(--warning);
}

.detail-visual {
  min-width: 0;
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent-2) 42%, var(--line));
  border-radius: 28px;
  background:
    radial-gradient(circle at 30% 20%, rgba(255, 221, 94, .18), transparent 38%),
    var(--surface);
  box-shadow: 0 30px 90px rgba(0, 0, 0, .32), 0 0 70px var(--glow);
}

.detail-visual-agent {
  aspect-ratio: 1 / 1;
}

.detail-visual-wide {
  aspect-ratio: 16 / 11;
}

.detail-visual img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.detail-visual-wide img {
  object-position: 62% center;
}

.detail-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 62%, color-mix(in srgb, var(--bg) 88%, transparent));
}

.detail-visual > span {
  position: absolute;
  z-index: 1;
  left: 20px;
  bottom: 18px;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 999px;
  background: rgba(7, 7, 27, .58);
  color: #fff;
  backdrop-filter: blur(12px);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .14em;
}

.content-section {
  padding: clamp(56px, 6vw, 72px) 0;
  border-bottom: 1px solid var(--line);
}

.content-heading {
  max-width: 72ch;
  margin-bottom: clamp(24px, 3vw, 32px);
}

.content-heading > span,
.detail-cta > div:first-child > span,
.callout-panel > div > span,
.company-panel > div > span {
  color: var(--accent-2);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .16em;
}

.content-heading h2,
.detail-cta h2,
.callout-panel h2,
.release-panel h2,
.contact-information h2,
.company-panel h2,
.prompt-example h2,
.case-study-panel h2 {
  margin: 13px 0;
  font-size: clamp(32px, 4.4vw, 52px);
  line-height: 1.1;
  letter-spacing: -.05em;
}

.content-heading p,
.detail-cta p,
.callout-panel > p,
.release-panel p,
.contact-information p,
.prompt-example > p,
.case-study-panel p {
  margin: 0;
  color: var(--muted);
  max-width: 68ch;
  font-size: 14px;
  line-height: 1.65;
}

.content-grid {
  display: grid;
  gap: 14px;
}

.content-grid-four {
  grid-template-columns: repeat(auto-fit, minmax(min(230px, 100%), 1fr));
}

.content-grid-three {
  grid-template-columns: repeat(auto-fit, minmax(min(280px, 100%), 1fr));
}

.fact-card,
.guide-card {
  min-width: 0;
  min-height: 190px;
  padding: clamp(20px, 2.6vw, 26px);
  border: 1px solid var(--line);
  border-radius: 19px;
  background: var(--surface-soft);
  display: flex;
  flex-direction: column;
  transition: transform .2s ease, border-color .2s ease, background .2s ease;
}

.fact-card:hover,
.guide-card:hover {
  transform: translateY(-3px);
  border-color: color-mix(in srgb, var(--accent-2) 46%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-soft));
}

.fact-card small,
.guide-card small {
  color: var(--accent-2);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .15em;
}

.fact-card h3,
.guide-card h3 {
  margin: 18px 0 10px;
  font-size: 20px;
  line-height: 1.25;
  letter-spacing: -.035em;
}

.fact-card p,
.guide-card p {
  margin: 0;
  color: var(--muted);
  max-width: 62ch;
  font-size: 13px;
  line-height: 1.62;
}

.readable-copy {
  max-width: 68ch;
}

.compact-flow {
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  list-style: none;
}

.compact-flow li {
  min-width: 0;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--surface-soft);
  display: grid;
  gap: 14px;
}

.compact-flow li > span {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-soft));
  color: var(--accent-2);
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 850;
}

.compact-flow strong {
  font-size: 14px;
  line-height: 1.45;
}

.purchase-inquiry-form {
  max-width: 860px;
  padding: clamp(22px, 4vw, 38px);
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--surface);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .16);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.form-field {
  min-width: 0;
  display: grid;
  gap: 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 750;
}

.form-field-wide {
  grid-column: 1 / -1;
}

.form-field small {
  color: var(--muted);
  font-weight: 600;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-solid);
  color: var(--text);
}

.form-field textarea {
  min-height: 132px;
  resize: vertical;
  line-height: 1.65;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--accent-2);
  outline: 2px solid color-mix(in srgb, var(--accent-2) 35%, transparent);
  outline-offset: 1px;
}

.consent-check {
  margin-top: 20px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.65;
}

.consent-check input {
  width: 18px;
  height: 18px;
  margin-top: 2px;
}

.consent-check a,
.form-availability a {
  color: var(--accent-2);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.form-availability,
.form-status {
  margin: 18px 0 0;
  padding: 13px 15px;
  border-inline-start: 3px solid var(--accent-2);
  border-radius: 8px;
  background: var(--surface-soft);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.65;
}

.form-status[data-tone="success"] {
  border-color: var(--positive);
  color: var(--text);
}

.form-status[data-tone="error"] {
  border-color: var(--danger);
  background: var(--danger-soft);
  color: var(--danger);
}

.form-submit {
  margin-top: 20px;
}

.form-submit:disabled {
  cursor: wait;
  opacity: .65;
}

.turnstile-slot {
  min-height: 66px;
  margin-top: 18px;
}

.honeypot {
  position: absolute;
  left: -10000px;
  width: 1px;
  height: 1px;
  overflow: hidden;
}

.card-number {
  width: 42px;
  height: 42px;
  margin-bottom: 36px;
  border: 1px solid var(--line);
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--accent-2);
  font-size: 10px;
  font-weight: 850;
}

.card-number + small {
  margin-top: auto;
}

.card-status-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.feature-detail-card h3 {
  margin-top: 48px;
}

.split-section {
  display: grid;
  grid-template-columns: minmax(240px, .7fr) minmax(0, 1.3fr);
  gap: 70px;
  align-items: start;
}

.split-section .content-heading {
  margin-bottom: 0;
}

.workspace-story {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr;
  gap: 14px;
  align-items: center;
}

.workspace-story > div {
  min-height: 210px;
  padding: 23px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: var(--surface-soft);
  display: flex;
  flex-direction: column;
}

.workspace-story > div small {
  color: var(--accent-2);
  font-size: 8px;
  letter-spacing: .16em;
}

.workspace-story > div strong {
  margin-top: auto;
  font-size: 15px;
}

.workspace-story > div p {
  margin: 9px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}

.workspace-story > span {
  color: var(--accent-2);
}

.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.tag-cloud span,
.format-grid span {
  padding: 13px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-soft);
  color: var(--text);
  font-size: 11px;
  font-weight: 750;
}

.detail-cta,
.callout-panel,
.release-panel,
.contact-information,
.company-panel,
.prompt-example,
.case-study-panel,
.warning-panel {
  margin-top: 90px;
  padding: 44px;
  border: 1px solid var(--line);
  border-radius: 24px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 8%, transparent), color-mix(in srgb, var(--accent-2) 5%, transparent)),
    var(--surface);
}

.detail-cta,
.callout-panel,
.release-panel,
.contact-information,
.case-study-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(240px, .7fr);
  gap: 50px;
  align-items: center;
}

.detail-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}

.callout-panel {
  grid-template-columns: minmax(260px, .8fr) minmax(300px, 1.2fr) auto;
}

.callout-panel h2 {
  font-size: clamp(28px, 3.5vw, 42px);
}

.policy-compare {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.policy-compare article {
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface-soft);
}

.policy-compare ul {
  margin: 22px 0 0;
  padding-left: 20px;
  display: grid;
  gap: 12px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.policy-compare li::marker {
  color: var(--accent-2);
}

.detail-disclaimer {
  margin: 0 0 22px;
  font-size: 11px;
}

.pricing-detail-grid .price-card {
  min-width: 0;
}

.pricing-detail-grid .product-name {
  min-height: 0;
}

.release-panel > .primary-button {
  justify-self: end;
}

.contact-card .secondary-button {
  width: 100%;
  margin-top: auto;
}

.contact-information address {
  display: grid;
  justify-items: end;
  gap: 12px;
  font-style: normal;
}

.contact-information address a {
  color: var(--accent-2);
  font-size: clamp(18px, 2.6vw, 28px);
  font-weight: 800;
  letter-spacing: -.03em;
}

.company-panel {
  display: grid;
  grid-template-columns: minmax(250px, 1fr) minmax(340px, 1.4fr) auto;
  gap: 35px;
  align-items: center;
}

.company-panel h2 {
  font-size: clamp(25px, 3.5vw, 38px);
}

.company-panel dl {
  margin: 0;
  display: grid;
  gap: 14px;
}

.company-panel dl > div {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 18px;
}

.company-panel dt {
  color: var(--muted);
  font-size: 10px;
}

.company-panel dd {
  margin: 0;
  color: var(--text);
  font-size: 11px;
  line-height: 1.65;
}

/* Guide pages */

.process-list,
.compact-steps {
  margin: 0;
  padding: 0;
  list-style: none;
}

.process-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.process-list li {
  min-height: 0;
  padding: 22px 24px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface-soft);
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 14px;
  align-content: start;
}

.process-list li > span,
.compact-steps li > span {
  color: var(--accent-2);
  font-size: 10px;
  font-weight: 850;
}

.process-list h3 {
  margin: 0 0 9px;
  font-size: 18px;
  letter-spacing: -.03em;
}

.process-list p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.62;
}

.process-list-detailed {
  max-width: 900px;
  margin-inline: auto;
  grid-template-columns: 1fr;
}

.process-list-detailed li {
  min-height: 0;
  grid-template-columns: 70px 1fr;
}

.guide-hub-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.guide-card {
  min-height: 250px;
}

.guide-card h3 {
  margin-top: 50px;
}

.guide-card b {
  margin-top: auto;
  color: var(--accent-2);
  font-size: 11px;
}

.prompt-example {
  grid-template-columns: .72fr 1.28fr;
  display: grid;
  gap: 42px;
  align-items: start;
}

.prompt-example blockquote {
  margin: 0;
  padding: 28px;
  border-inline-start: 3px solid var(--accent-2);
  border-radius: 0 15px 15px 0;
  background: var(--surface-soft);
  color: var(--text);
  font-size: 17px;
  line-height: 1.8;
}

.prompt-example > p {
  grid-column: 2;
}

.format-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
}

.format-grid span {
  border-radius: 16px;
  text-align: center;
}

.compact-steps {
  border-top: 1px solid var(--line);
}

.compact-steps li {
  padding: 24px 4px;
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: 70px 1fr;
  gap: 18px;
}

.compact-steps p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

.case-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.case-metrics span {
  min-height: 110px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface-soft);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: var(--muted);
  font-size: 10px;
}

.case-metrics strong {
  color: var(--accent-2);
}

.warning-panel {
  margin-top: 70px;
  border-color: color-mix(in srgb, var(--warning) 32%, var(--line));
  background: var(--warning-soft);
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 20px;
  align-items: start;
}

.warning-panel strong {
  padding: 7px 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--warning) 13%, transparent);
  color: var(--warning);
  font-size: 10px;
}

.warning-panel p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.75;
}

@media (max-width: 1040px) {
  .section-topbar {
    position: relative;
    top: auto;
  }

  .section-mobile-nav {
    width: min(1120px, calc(100% - 40px));
    margin: 12px auto 0;
    padding: 8px;
    position: sticky;
    top: 12px;
    z-index: 24;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: var(--nav);
    backdrop-filter: blur(18px);
    display: flex;
    gap: 5px;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .section-mobile-nav::-webkit-scrollbar {
    display: none;
  }

  .section-mobile-nav a {
    min-width: max-content;
    padding: 9px 12px;
    border-radius: 9px;
    color: var(--muted);
    font-size: 10px;
    font-weight: 750;
  }

  .section-mobile-nav a.active {
    background: var(--surface-soft);
    color: var(--accent-2);
  }

  .detail-hero {
    grid-template-columns: minmax(0, 1fr) minmax(300px, .8fr);
    gap: 42px;
  }

  .content-grid-four {
    grid-template-columns: 1fr 1fr;
  }

  .compact-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .process-list:not(.process-list-detailed) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split-section {
    grid-template-columns: 1fr;
    gap: 34px;
  }

  .callout-panel,
  .company-panel {
    grid-template-columns: 1fr;
  }

  .callout-panel > a,
  .company-panel > a {
    justify-self: start;
  }
}

/* Product-led brand refresh */

.site-shell,
.privacy-shell,
.home-shell {
  background: var(--bg);
  transition: background-color .3s ease, color .3s ease;
}

.ambient {
  display: none;
}

.topbar {
  width: 100%;
  height: 72px;
  margin: 0;
  padding-inline: max(20px, calc((100% - 1180px) / 2));
  top: 0;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--nav);
  box-shadow: none;
}

.brand-avatar,
.assistant-avatar,
.support-card img {
  border: 0;
  border-radius: 7px;
  box-shadow: none;
  object-fit: contain;
}

.brand-avatar {
  width: 34px;
  height: 34px;
}

.brand > span {
  font-size: 15px;
  letter-spacing: .01em;
}

.brand small {
  padding-inline-start: 10px;
  border-inline-start: 1px solid var(--line);
  font-size: 9px;
  letter-spacing: .08em;
}

.theme-trigger,
.language-trigger,
.install-small,
.theme-menu,
.language-menu,
.theme-option,
.language-option,
.custom-link,
.custom-panel,
.custom-preview,
.color-controls label,
.custom-actions button {
  border-radius: 5px;
}

.theme-menu,
.language-menu {
  background: var(--surface-solid);
  box-shadow: var(--shadow);
}

.install-small,
.primary-button {
  background: var(--accent);
  color: var(--accent-text);
  box-shadow: none;
}

.primary-button,
.secondary-button {
  border-radius: 4px;
}

.primary-button:hover,
.install-small:hover {
  background: color-mix(in srgb, var(--accent) 86%, black);
}

.secondary-button {
  background: transparent;
}

.section-nav a::after {
  border-radius: 0;
  background: var(--accent);
}

.home-shell .home-hero,
:root[data-theme="synthwave"] .home-shell .home-hero {
  width: min(1180px, calc(100% - 40px));
  min-height: 0;
  margin: 0 auto;
  padding: 106px 0 76px;
  display: block;
  overflow: visible;
  text-align: left;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.home-shell .home-hero::before,
.home-shell .home-hero::after {
  content: none;
}

.home-shell .eyebrow {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--accent);
}

.home-shell .eyebrow span {
  width: 18px;
  height: 2px;
  border-radius: 0;
  background: var(--accent);
  box-shadow: none;
}

.home-shell .home-hero h1,
:root[data-theme="synthwave"] .home-shell .home-hero h1 {
  max-width: 940px;
  margin: 30px 0 24px;
  font-size: clamp(52px, 7vw, 86px);
  color: var(--text);
  text-shadow: none;
}

.home-shell .home-hero h1 em {
  color: var(--accent);
  background: none;
}

.home-shell .home-hero > p,
:root[data-theme="synthwave"] .home-shell .home-hero > p {
  max-width: 760px;
  margin: 0;
  color: var(--muted);
  text-shadow: none;
}

.home-shell .hero-actions,
.home-shell .trust-row,
:root[data-theme="synthwave"] .home-shell .hero-actions,
:root[data-theme="synthwave"] .home-shell .trust-row {
  justify-content: flex-start;
}

.home-workbench {
  margin-bottom: 124px;
  border-color: var(--line);
  border-radius: 6px;
  background: var(--surface-solid);
  box-shadow: 0 20px 55px rgba(15, 42, 70, .11);
  backdrop-filter: none;
}

.home-workbench-topline {
  min-height: 50px;
  padding-inline: 20px;
  background: var(--surface-soft);
}

.live i,
.payment-status i {
  box-shadow: none;
}

.home-workbench-grid {
  min-height: 480px;
  grid-template-columns: minmax(190px, .68fr) minmax(390px, 1.65fr) minmax(220px, .82fr);
}

.home-context-list,
.home-action-list {
  gap: 0;
}

.home-context-list > div,
.home-action-list > div {
  min-height: 58px;
  padding: 12px 0;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-context-list > div.active {
  padding-inline: 10px;
  border: 0;
  border-inline-start: 3px solid var(--accent);
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
}

.home-context-list span,
.home-action-list span {
  border: 0;
  border-radius: 4px;
  background: var(--surface-soft);
  color: var(--accent);
}

.home-user-prompt {
  border-radius: 4px;
  background: var(--accent);
  color: var(--accent-text);
}

.home-mini-flow {
  gap: 0;
  border-block: 1px solid var(--line);
}

.home-mini-flow li,
.home-mini-flow li.complete {
  border: 0;
  border-inline-end: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-mini-flow li:last-child {
  border-inline-end: 0;
}

.home-mini-flow li.complete::after {
  width: 100%;
  border-radius: 0;
  background: var(--accent);
}

.home-role-section,
.home-capability-section {
  padding-bottom: 124px;
}

.home-role-grid {
  gap: 0;
  border-block: 1px solid var(--line);
}

.home-role-grid article {
  min-height: 245px;
  padding: 30px;
  border: 0;
  border-inline-end: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-role-grid article:last-child {
  border-inline-end: 0;
}

.home-role-grid article > span {
  width: auto;
  height: auto;
  border: 0;
  border-radius: 0;
  color: var(--accent);
  place-items: start;
  font-family: var(--font-geist-mono), monospace;
}

.home-flow-section {
  margin-bottom: 124px;
  padding: 70px 0;
  border: 0;
  border-block: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-flow-list li {
  grid-template-columns: 48px minmax(0, 1fr);
}

.home-flow-list li > span {
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
}

.home-capability-grid {
  grid-template-columns: 1fr;
  gap: 0;
  border-top: 1px solid var(--line);
}

.home-capability-grid article {
  min-height: 0;
  padding: 22px 0;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
  display: grid;
  grid-template-columns: minmax(180px, .65fr) minmax(180px, .55fr) minmax(260px, 1.3fr);
  gap: 28px;
  align-items: center;
}

.home-capability-card-top {
  display: contents;
}

.home-capability-grid h3 {
  margin: 0;
}

.home-capability-card-top b,
.status-pill,
.mini-status,
.recommended {
  border-radius: 3px;
}

.home-capability-card-top b {
  max-width: 190px;
  justify-self: start;
  padding: 7px 9px;
  border-color: color-mix(in srgb, var(--accent) 24%, var(--line));
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
  color: var(--accent);
  text-align: left;
}

.home-capability-grid p {
  font-size: 13px;
}

.home-boundary-section {
  margin-bottom: 0;
  padding: 74px 0;
  border: 0;
  border-block: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-boundary-grid {
  gap: 0;
  border-top: 1px solid var(--line);
}

.home-boundary-grid article {
  min-height: 190px;
  padding: 26px;
  border: 0;
  border-inline-end: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.home-boundary-grid article:last-child {
  border-inline-end: 0;
}

.home-runtime-details {
  border-radius: 4px;
  background: var(--surface-soft);
}

.payment-status,
.price-card,
.support-card,
.business-details {
  border-radius: 4px;
}

.price-card {
  border-color: var(--line);
  background: var(--surface);
  overflow: visible;
}

.price-card::before {
  content: none;
}

.price-card.featured {
  border-color: var(--accent);
  background: var(--surface);
  box-shadow: none;
}

.recommended {
  background: color-mix(in srgb, var(--accent) 9%, transparent);
  color: var(--accent);
}

.support-card {
  background: var(--surface-soft);
}

.support-card img {
  background: transparent;
}

.detail-shell {
  background: var(--bg);
}

.detail-visual {
  aspect-ratio: 16 / 11;
  border-color: var(--line);
  border-radius: 6px;
  background: var(--surface-solid);
  box-shadow: 0 20px 55px rgba(15, 42, 70, .12);
}

.detail-visual::after {
  content: none;
}

.browser-preview-titlebar {
  min-height: 52px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--surface-soft);
  display: grid;
  grid-template-columns: 28px 1fr auto;
  gap: 10px;
  align-items: center;
}

.browser-preview-titlebar img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

.browser-preview-titlebar strong {
  font-size: 12px;
}

.browser-preview-titlebar span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .12em;
}

.browser-preview-body {
  min-height: 360px;
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr);
}

.browser-preview-body aside {
  padding: 20px 16px;
  border-inline-end: 1px solid var(--line);
  display: grid;
  align-content: start;
  gap: 8px;
  color: var(--muted);
  font-size: 10px;
}

.browser-preview-body aside small {
  margin-bottom: 10px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.browser-preview-body aside b,
.browser-preview-body aside span {
  padding: 9px 10px;
  border-radius: 3px;
}

.browser-preview-body aside b {
  border-inline-start: 2px solid var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  color: var(--text);
}

.browser-preview-body > section {
  padding: 24px;
}

.browser-preview-status {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.browser-preview-status b {
  color: var(--accent);
}

.browser-preview-body h3 {
  margin: 30px 0 20px;
  font-size: 21px;
  letter-spacing: -.035em;
}

.browser-preview-field {
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
  display: grid;
  gap: 6px;
}

.browser-preview-field small {
  color: var(--accent);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.browser-preview-field span {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.browser-preview-body button {
  width: 100%;
  min-height: 38px;
  margin-top: 22px;
  border: 0;
  border-radius: 3px;
  background: var(--accent);
  color: var(--accent-text);
  font-size: 10px;
  font-weight: 800;
}

.detail-visual > .detail-visual-label {
  left: auto;
  right: 14px;
  bottom: 12px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--muted);
  backdrop-filter: none;
}

.fact-card,
.guide-card {
  border-radius: 4px;
  background: var(--surface);
}

.fact-card:hover,
.guide-card:hover {
  transform: none;
  background: var(--surface);
}

.tag-cloud span,
.format-grid span,
.compact-flow li {
  border-radius: 4px;
}

.detail-cta,
.callout-panel,
.release-panel,
.contact-information,
.company-panel,
.prompt-example,
.case-study-panel,
.warning-panel {
  border-radius: 4px;
  background: var(--surface);
}

