  }

  .compact-flow,
  .form-grid {
    grid-template-columns: 1fr;
  }

  .compact-flow li {
    padding: 16px;
    grid-template-columns: auto 1fr;
    align-items: center;
  }

  .purchase-inquiry-form {
    padding: 20px;
  }

  .detail-cta,
  .callout-panel,
  .release-panel,
  .contact-information,
  .company-panel,
  .prompt-example,
  .case-study-panel,
  .warning-panel {
    margin-top: 64px;
    padding: 25px;
    border-radius: 19px;
  }

  .callout-panel {
    grid-template-columns: 1fr;
    gap: 26px;
  }

  .detail-actions,
  .detail-actions a,
  .release-panel > .primary-button {
    width: 100%;
  }

  .business-details {
    grid-template-columns: 1fr;
    padding: 20px;
  }

  .site-footer {
    margin-top: 86px;
    padding-bottom: 42px;
    grid-template-columns: minmax(0, 1fr);
  }

  .site-footer .footer-links {
    width: 100%;
    justify-content: flex-start;
    gap: 12px 16px;
  }

  .site-footer .footer-links a {
