@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* AIWORK safe orchestration homepage */

.home-shell {
  background:
    radial-gradient(circle at 74% 4%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 28%),
    radial-gradient(circle at 12% 32%, color-mix(in srgb, var(--accent-2) 10%, transparent), transparent 26%),
    linear-gradient(180deg, color-mix(in srgb, var(--bg) 92%, var(--accent) 8%), var(--bg) 34%);
}

.home-hero > p {
  max-width: 760px;
  margin-inline: auto;
}

:root[data-theme="synthwave"] .home-hero > p {
