/* Final AIWORK product identity */

.product-mark {
  --mark-size: 40px;
  --mark-scale: 1.24;
  --mark-origin-y: 43%;
  width: var(--mark-size);
  height: var(--mark-size);
  position: relative;
  display: block;
  flex: 0 0 auto;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 36%, var(--line));
  border-radius: 50%;
  background: color-mix(in srgb, var(--surface-solid) 82%, var(--accent) 18%);
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 12%, transparent),
    0 6px 18px color-mix(in srgb, var(--accent) 14%, transparent);
  isolation: isolate;
  contain: paint;
  transition:
    border-color .3s ease,
    background-color .3s ease,
    box-shadow .3s ease;
}

.product-mark img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  border-radius: inherit;
  object-fit: cover;
  object-position: 50% 45%;
  transform: scale(var(--mark-scale));
  transform-origin: 50% var(--mark-origin-y);
  image-rendering: auto;
  user-select: none;
}

.product-mark-character {
  position: absolute;
  inset: 0;
  display: none;
}

:root:not([data-character]) .product-mark-character[data-character-layer="aiwork"],
:root[data-character="aiwork"] .product-mark-character[data-character-layer="aiwork"],
:root[data-character="planner"] .product-mark-character[data-character-layer="planner"] {
  display: block;
}

.product-mark-image-open {
  z-index: 1;
  opacity: 1;
}

.product-mark-image-wink {
  z-index: 2;
  opacity: 0;
}

.product-mark.is-touch-winking .product-mark-image-open {
  opacity: 0;
}

.product-mark.is-touch-winking .product-mark-image-wink {
  opacity: 1;
}

.product-mark::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #ffffff 48%, transparent);
  pointer-events: none;
}

.brand-product-mark {
  --mark-size: 40px;
  --mark-scale: 1.32;
}

.footer-product-mark {
  --mark-size: 36px;
  --mark-scale: 1.32;
  box-shadow: none;
}

.home-product-mark {
  --mark-size: 64px;
  --mark-scale: 1.1;
  margin: 0;
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 12%, transparent),
    0 8px 24px color-mix(in srgb, var(--accent) 18%, transparent),
    0 0 0 3px color-mix(in srgb, var(--accent) 8%, transparent);
}

.assistant-product-mark {
  --mark-size: 44px;
  --mark-scale: 1.26;
  box-shadow: 0 1px 3px color-mix(in srgb, var(--text) 12%, transparent);
}

.support-product-mark {
  --mark-size: 54px;
  --mark-scale: 1.16;
}

.preview-product-mark {
  --mark-size: 32px;
  --mark-scale: 1.45;
  box-shadow: none;
}

:root[data-character="planner"] .product-mark {
  --mark-scale: 1.04;
  --mark-origin-y: 46%;
}

:root[data-character="planner"] .product-mark.brand-product-mark,
:root[data-character="planner"] .product-mark.footer-product-mark,
:root[data-character="planner"] .product-mark.preview-product-mark {
  --mark-scale: 1.08;
}

:root[data-character="planner"] .product-mark.assistant-product-mark,
:root[data-character="planner"] .product-mark.support-product-mark {
  --mark-scale: 1.02;
}

:root[data-character="planner"] .product-mark.home-product-mark {
  --mark-scale: 1;
}

