app/cinematic-theme.css:
/* Shared cinematic scene. Foreground themes never recolor the approved artwork. */
:root {
  --cinematic-veil: color-mix(in srgb, var(--bg) 68%, transparent);
  --cinematic-panel: color-mix(in srgb, var(--surface-solid) 72%, transparent);
  --cinematic-border: color-mix(in srgb, var(--accent) 32%, var(--line));
  --cinematic-blur: 4px;
  --cinematic-strong-blur: 6px;
}
.aiwork-cinematic-scene {
  position: fixed; inset: 0; z-index: 0; isolation: isolate;
  pointer-events: none; user-select: none; overflow: hidden;
  contain: strict;
  background: #000704 url("/assets/aiwork-matrix-structure.svg") 50% 50% / cover no-repeat;
}
.aiwork-cinematic-scene > picture,
.aiwork-cinematic-scene > picture > img,
.aiwork-cinematic-scene > canvas {
  position: absolute; inset: 0; width: 100%; height: 100%;
  object-fit: cover; object-position: 50% 50%; pointer-events: none;
}
.aiwork-cinematic-scene > picture > .cinematic-scene-poster {
  opacity: .98; object-position: 50% 46%;
}
.aiwork-cinematic-scene > canvas { mix-blend-mode: screen; opacity: .82; }
.aiwork-cinematic-scene::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(180deg, #00060329, transparent 38%, #00060318 65%, #00060335);
}
.aiwork-cinematic-content { position: relative; min-width: 0; background: transparent; }
body .aiwork-cinematic-content :is(.site-shell, .home-shell, .privacy-shell, .research-page, .hashcat-page) {
  background: transparent; z-index: auto; isolation: auto;
}
/* Keep the header in the root stacking order, above the floating motion controls. */
/* Readable content surfaces leave the scene visible through and between sections. */
:root body .aiwork-cinematic-content .site-shell :is(
  .home-hero, .detail-hero, .content-section, .home-flow-section,
  .home-capability-section, .home-boundary-section, .home-role-section,
  .payment-section, .contact-information, .detail-cta, .detail-disclaimer
) { background: var(--cinematic-veil); }
body .aiwork-cinematic-content .home-shell .home-hero {
  padding-inline: clamp(18px, 3vw, 42px);
  margin-block: 24px 42px;
  border: 1px solid var(--cinematic-border);
}
:root body .aiwork-cinematic-content .site-shell :is(
  .home-workbench, .fact-card, .price-card, .home-capability-card,
  .home-digital-card, .detail-visual, .home-role-grid article,
  .home-boundary-grid article, .home-runtime-details, .support-card,
  .purchase-form, .browser-preview
) {
  background: var(--cinematic-panel);
  border-color: var(--cinematic-border);
  backdrop-filter: blur(var(--cinematic-blur));
  -webkit-backdrop-filter: blur(var(--cinematic-blur));
}
body .aiwork-cinematic-content .privacy-document {
  padding: clamp(18px, 4vw, 48px); background: var(--cinematic-panel);
}
body .aiwork-cinematic-content :is(.secondary-button, .theme-trigger, .language-trigger, .availability-notice) {
  background: var(--cinematic-panel); color: var(--text);
}
body .aiwork-cinematic-content .site-footer {
  width: min(1180px, calc(100% - 40px));
  margin-inline: auto; padding-inline: clamp(18px, 3vw, 36px);
  background: color-mix(in srgb, var(--surface-solid) 80%, transparent);
